BEGIN;
WITH e AS (INSERT INTO empresas(razao_social,nome_fantasia,documento,telefone,email) VALUES('Sensor Delivery LTDA','Sensor Delivery','00000000000000','48999999999','contato@sensordelivery.local') ON CONFLICT(documento) DO UPDATE SET nome_fantasia=EXCLUDED.nome_fantasia RETURNING id),u AS (INSERT INTO usuarios(nome,email,senha_hash,tipo) VALUES('Administrador','admin@sensordelivery.local',crypt('Sensor@123',gen_salt('bf',12)),'ADMIN') ON CONFLICT(email) DO UPDATE SET nome=EXCLUDED.nome,tipo='ADMIN',ativo=TRUE RETURNING id),v AS (INSERT INTO usuario_empresas(usuario_id,empresa_id,principal) SELECT u.id,e.id,TRUE FROM u CROSS JOIN e ON CONFLICT(usuario_id,empresa_id) DO UPDATE SET principal=TRUE) INSERT INTO whatsapp_sessoes(empresa_id,nome,client_id) SELECT id,'WhatsApp Principal','sensor-delivery-principal' FROM e ON CONFLICT(empresa_id,client_id) DO NOTHING;
INSERT INTO categorias(empresa_id,nome,descricao,ordem) SELECT id,'Pizzas','Pizzas tradicionais e especiais',1 FROM empresas WHERE documento='00000000000000' ON CONFLICT(empresa_id,nome) DO NOTHING;
COMMIT;
